/* ---------- content ---------- */
const QUESTIONS = {
  cranial: [
    { q: 'Which cranial nerve nucleus lies in the midbrain at the level of the superior colliculus?', o: ['Trochlear nucleus', 'Abducens nucleus', 'Oculomotor nucleus', 'Facial motor nucleus'], a: 2, e: 'The oculomotor nucleus lies at the superior colliculus level; the trochlear nucleus is at the inferior colliculus, and abducens and facial nuclei are in the pons.' },
    { q: 'The nucleus ambiguus supplies motor fibres through which cranial nerves?', o: ['V and VII', 'IX, X and the cranial root of XI', 'XII only', 'III and IV'], a: 1, e: 'Nucleus ambiguus is a special visceral efferent column supplying pharyngeal and laryngeal muscles via IX, X and the cranial root of XI.' },
    { q: 'The nucleus tractus solitarius mainly receives:', o: ['Proprioception from the face', 'Taste and general visceral afferents', 'Hearing', 'Pain from the cornea'], a: 1, e: 'NTS receives special visceral afferent (taste) from VII, IX, X and general visceral afferents from IX and X.' },
    { q: 'Which cranial nerve has the longest intracranial course?', o: ['Abducens', 'Trochlear', 'Optic', 'Hypoglossal'], a: 1, e: 'The trochlear nerve has the longest intracranial course and is the only nerve to emerge from the dorsal brainstem.' },
    { q: 'On protrusion, the tongue deviates in a lower motor neuron lesion of the hypoglossal nerve:', o: ['Towards the side of the lesion', 'Away from the side of the lesion', 'Does not deviate', 'Downwards'], a: 0, e: 'The intact genioglossus pushes the tongue towards the paralysed side.' },
    { q: 'The facial colliculus is formed by:', o: ['The abducens nerve looping around the facial nucleus', 'Facial nerve fibres looping around the abducens nucleus', 'The vestibular nuclei', 'The hypoglossal trigone'], a: 1, e: 'Motor fibres of the facial nerve loop around the abducens nucleus in the pons, raising the facial colliculus on the floor of the fourth ventricle.' },
  ],
};
