const videoCard = (v) => `<article class="card item ${v.free ? '' : 'pro-card'}" style="min-height:128px">
  <div class="thumb ${v.img ? 'has-img' : ''}">${v.img ? `<img src="${v.img}" alt="" loading="lazy" decoding="async">` : `<span class="person">${I.person}</span>`}${v.free ? '' : `<span class="lock-veil"><button class="lock-dot" data-action="play" data-arg="${v.id}" aria-label="${v.title} is a Pro video. See Pro plans"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="11" width="16" height="10" rx="2.5"/><path d="M8 11V7.5a4 4 0 0 1 8 0V11"/><circle cx="12" cy="16" r="1.3" fill="currentColor" stroke="none"/></svg></button></span>`}${v.progress != null ? `<span class="vprog" aria-label="${v.progress}% watched"><i style="width:${v.progress}%"></i></span>` : ''}<span class="badge ${v.free ? '' : 'pro-badge'}">${v.free ? 'Free' : '<svg width="12" height="12" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7l4.5 4L12 4l4.5 7L21 7l-2 12H5z" fill="currentColor"/></svg>PRO'}</span></div>
  <div class="body">
    <span class="title b">${v.title}</span><span class="chip">${v.tag}</span>
    <div class="foot" style="display:flex;align-items:center;gap:14px"><span class="meta" style="color:var(--body)"><span style="color:var(--brand);display:flex">${I.star}</span>${v.rating}</span><span class="meta num">${I.clock}${v.dur}</span>
      ${S.watched.includes(v.id) ? '<span class="kchip c">Watched</span>' : ''}
      ${v.free ? `<button class="round" style="margin-left:auto" data-action="play" data-arg="${v.id}" aria-label="Play ${v.title}">${I.play}</button>` : ''}</div>
  </div></article>`;
