function psFilter(v) {
  const q = (v || '').trim().toLowerCase();
  let shown = 0, total = 0;
  document.querySelectorAll('#view .subj, #view .res, #view .lcard, #view .qb-list .item, #view .tr-row').forEach((el) => { total++; const hit = !q || el.textContent.toLowerCase().includes(q); el.hidden = !hit; if (hit) shown++; });
  const e = $('#psearch-empty'); if (e) { e.hidden = !q || shown > 0; e.textContent = q ? `No matches for “${v.trim()}” on this page.` : ''; }
}
function psOpen() { const w = $('#psearch'); if (!w) return; w.classList.add('open'); const i = $('#psearch-in'); i.tabIndex = 0; $('.psearch-x').tabIndex = 0; $('.psearch-btn').setAttribute('aria-expanded', 'true'); setTimeout(() => i.focus(), 60); }
