const qbResult = (q) => {
  const total = qbTotal(q);
  if (q.lastAns && Object.keys(q.lastAns).length) {
    const keys = Object.keys(q.lastAns).map(Number);
    const correct = keys.filter((n) => q.lastAns[n] === qAt(n).a).length;
    return { total, attempted: keys.length, correct, incorrect: keys.length - correct, unanswered: total - keys.length, ans: q.lastAns, avg: 24 };
  }
  const attempted = Math.round(total * 0.9), correct = Math.round(attempted * 0.62);
  const ans = {}; for (let n = 1; n <= attempted; n++) { const a = qAt(n).a; ans[n] = n <= correct ? a : (a + 1) % 4; }
  return { total, attempted, correct, incorrect: attempted - correct, unanswered: total - attempted, ans, avg: 28 };
};
