  'agent-close': () => setAgent('closed'),
  'chat-say': (t) => say(t),
  'chat-new': () => { CHATS.current = { title: 'New chat', msgs: [] }; activeChat = 'current'; render(); },
  'chat-open': (k) => { activeChat = k; route === 'ai' ? render() : drawPanel(); },
